         PlantCrop(2, 1),              # \240\159\140\191 below #\n\
         PlantCrop(1, 0),              # \240\159\140\191 left #\n\
         PlantCrop(1, 2),              # \240\159\140\191 right #\n\
         CalculateHealth,\n\
