         PlantCrop(2, 1),              # \240\159\141\132 below: -10 #\n\
         PlantCrop(1, 0),              # \240\159\141\132 left: -10 #\n\
         PlantCrop(1, 2),              # \240\159\141\132 right: -10 #\n\
         CalculateHealth\n\
         ]) in\n\
         healthAt(m, 1, 1) >= 0\n\
